def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    for o in objects(g, bg=bg):
        y0, x0, y1, x1 = o["box"]
        # find the gap in the top edge
        gaps = [x for x in range(x0, x1 + 1) if g[y0, x] == bg]
        if not gaps:
            continue
        gx = gaps[0]
        # fill every empty cell inside the cup's bounding box
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if out[y, x] == bg:
                    out[y, x] = 2
        emit(out, f"Fill the cup at rows {y0}-{y1}, cols {x0}-{x1} (including its top gap at x={gx}) with red.")
        # draw a line on the row above, from the gap toward the side with more wall
        ly = y0 - 1
        if ly >= 0:
            centre = (x0 + x1) / 2
            xs = range(gx, g.shape[1]) if gx < centre else range(gx, -1, -1)
            for x in xs:
                if out[ly, x] == bg:
                    out[ly, x] = 2
            d = "right" if gx < centre else "left"
            emit(out, f"Draw a red line on row {ly} from above the gap (x={gx}) {d} to the border.")
    emit(out, "Final grid.")
    return out
